<section class="form-box" @if($inLesson) data-sortable-sections data-reorder-url="{{ route('admin.activities.lessons.sections.reorder',[$activity,$lesson]) }}" data-csrf="{{ csrf_token() }}" @endif>@forelse(($inLesson ? $lesson->sections : $activity->sections) as $section)<article class="progress-line sortable-section" @if($inLesson) draggable="true" data-sort-id="{{ $section->id }}" @endif><strong>{{ $section->position }}. {{ $section->title }}</strong><span>{{ ucfirst(str_replace('_',' ',$section->content_type)) }}</span>@if($inLesson)<span class="section-actions"><a href="{{ route('admin.activities.lessons.sections.create',[$activity,$lesson,'position'=>$section->position]) }}">Before</a><a href="{{ route('admin.activities.lessons.sections.create',[$activity,$lesson,'position'=>$section->position+1]) }}">After</a><a href="{{ route('admin.activities.lessons.sections.edit',[$activity,$lesson,$section]) }}">Edit</a><form method="POST" action="{{ route('admin.activities.lessons.sections.duplicate',[$activity,$lesson,$section]) }}">@csrf<button class="btn btn-outline btn-small">Duplicate</button></form><form method="POST" action="{{ route('admin.activities.lessons.sections.destroy',[$activity,$lesson,$section]) }}" onsubmit="return confirm('Delete this section?')">@csrf @method('DELETE')<button class="btn btn-red btn-small">Delete</button></form></span>@else<a href="{{ route('admin.activities.sections.edit',[$activity,$section]) }}">Edit</a><form method="POST" action="{{ route('admin.activities.sections.destroy',[$activity,$section]) }}" onsubmit="return confirm('Delete this section?')">@csrf @method('DELETE')<button class="btn btn-red btn-small">Delete</button></form>@endif</article>@empty<div class="empty-state"><h2>No content has been added to this lesson yet.</h2><p>This lesson is empty. Add one section at a time; no default content is created.</p>@if($inLesson)<a class="btn btn-blue" href="{{ route('admin.activities.lessons.sections.create',[$activity,$lesson]) }}">+ Add Your First Section</a>@endif</div>@endforelse</section>
@if($inLesson)<script>(function(){var list=document.querySelector('[data-sortable-sections]'),dragged=null;if(!list)return;list.querySelectorAll('[data-sort-id]').forEach(function(row){row.addEventListener('dragstart',function(){dragged=row});row.addEventListener('dragover',function(e){e.preventDefault();if(dragged&&dragged!==row){var r=row.getBoundingClientRect();list.insertBefore(dragged,e.clientY<r.top+r.height/2?row:row.nextSibling)}});row.addEventListener('dragend',function(){var order=[].slice.call(list.querySelectorAll('[data-sort-id]')).map(function(x){return x.dataset.sortId});fetch(list.dataset.reorderUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':list.dataset.csrf},body:JSON.stringify({order:order})}).then(function(){location.reload()})})})})();</script>@endif
